// prefix[r+1][c+1] = sum of grid[0..r][0..c]
for (let r = 0; r < rows; r++) {
  for (let c = 0; c < columns; c++) {
    prefix[r + 1][c + 1] =
      grid[r][c] +
      prefix[r][c + 1] +      // rectangle above
      prefix[r + 1][c] -      // rectangle to the left
      prefix[r][c];           // overlap, counted twice
  }
}

function regionSum(prefix, r1, c1, r2, c2) {
  return prefix[r2 + 1][c2 + 1]
       - prefix[r1][c2 + 1]
       - prefix[r2 + 1][c1]
       + prefix[r1][c1];
}
